export const endingText=(value,locale='zh')=>value[locale]||value.zh;
export const escapeEnding=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function endingRollHtml(locale){const name=text('裂空回响','裂空回響','AERO ECHO'),sub=text('—— 黎明之后 ——','—— 夜明けの後に ——','— AFTER THE DAWN —');const t=v=>escapeEnding(endingText(v,locale));return `<header class="ending-heading"><small>${t(ENDING_TITLE)}</small><h1>${t(name)}</h1>${locale==='en'?'':'<b>AERO ECHO</b>'}<p>${t(sub)}</p></header>`+ENDING_PARAGRAPHS[locale].map((p,i)=>`<p class="${[9,11,23,24,25,30,46,47,48].includes(i)?'ending-emphasis':''}">${escapeEnding(p)}</p>`).join('');}
export function endingFinalHtml(locale){const t=v=>escapeEnding(endingText(v,locale));return `<p>${t(ENDING_UI.thanks)}</p><h2>AERO ECHO</h2><strong>${t(ENDING_UI.end)}</strong><p class="ending-dedication">${t(ENDING_DEDICATION)}</p>`;}
export function endingTeaserHtml(index,locale){const c=ENDING_TEASER[index],t=v=>escapeEnding(endingText(v,locale));return `${c.location?`<small>${t(c.location)}</small>`:''}<div class="${c.sequel?'ending-sequel':''}">${c.lines.map(l=>`<p>${t(l)}</p>`).join('')}</div>`;}
